def formula(a, b):
    # Pythagorean Theorem: compute hypotenuse from two legs
    return np.sqrt(a**2 + b**2)

def formula(P, r, n, t):
    # P = principal amount
    # r = annual interest rate (decimal)
    # n = number of compounding periods per year
    # t = time in years
    return P * np.power(1 + r / n, n * t)

def formula(A, K, L):
    # Cobb-Douglas production function
    # A: total factor productivity
    # K: capital input
    # L: labor input
    return A * np.power(K, 0.3) * np.power(L, 0.7)
